if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function downloadImage(fileName, index, total) {
    if (!fileName || typeof fileName !== 'string') return;

    // 1. Remove o prefixo "File:" (case-insensitive) antes de codificar a URL
    const normalizedName = fileName.trim().replace(/^File:/i, '');
    const cleanName = normalizedName.replace(/\.png$/i, '');

    const filenameHash = cleanName.replace(/[^a-zA-Z0-9]/g, '_') + '.png';
    const filePath = path.join(OUTPUT_DIR, filenameHash);

    // Se já existe localmente, pula
    if (fs.existsSync(filePath)) {
        console.log(`[${index + 1}/${total}] Já existe: ${filenameHash}`);
        return;
    }

    const encodedUrl = WIKI_FILE_URL + encodeURIComponent(fileName);

    try {
        const response = await fetch(encodedUrl, {
            redirect: 'follow',
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
            }
        });

        if (!response.ok) {
            console.warn(`[!] Erro ${response.status} ao baixar: ${normalizedName}`);
            return;
        }

        // Salva usando Buffer (sem dependência de stream/finished)
        const arrayBuffer = await response.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        fs.writeFileSync(filePath, buffer);
        console.log(`[${index + 1}/${total}] Baixado com sucesso: ${filenameHash}`);
    } catch (err) {
        console.warn(`[!] Falha de rede para ${normalizedName}:`, err.message);
    }
}

async function start() {
    const uniqueIcons = [...new Set(itemsList.map(item => item.inventory_icon))].filter(Boolean);

    console.log(`Iniciando download de ${uniqueIcons.length} ícones únicos...`);

    for (let i = 0; i < uniqueIcons.length; i++) {
        await downloadImage(uniqueIcons[i], i, uniqueIcons.length);
        await delay(300); // Pausa de 300ms para proteger contra 429
    }

    console.log('✨ Download de todas as imagens concluído com sucesso!');
}

start();